const renderer=new THREE.WebGLRenderer({alpha:true,antialias:true});renderer.setPixelRatio(Math.min(devicePixelRatio,1.6));renderer.outputColorSpace=THREE.SRGBColorSpace;renderer.xr.enabled=true;renderer.xr.setReferenceSpaceType('local-floor');$('#view').append(renderer.domElement);
const camera=new THREE.PerspectiveCamera(48,1,.015,100);camera.position.set(0,1.35,1);const orbit=new OrbitControls(camera,renderer.domElement);orbit.target.set(0,1.3,-1.1);orbit.enableDamping=true;
