const room=new THREE.Group();room.visible=false;world.add(room);const floor=new THREE.Mesh(new THREE.CircleGeometry(6,64),new THREE.MeshStandardMaterial({color:0x263b2e,roughness:1}));floor.rotation.x=-Math.PI/2;room.add(floor);const grid=new THREE.GridHelper(12,24,0x648356,0x344c37);grid.position.y=.002;room.add(grid);
