let atlas,entries=[],active=null,cursor=3,kind='parts',snap=true,reference=false,busy=false,selectedPiece=null,undo=[],xrMode=null,pendingCenter=0,lastTime=0,notice='Gotowe',restoring=false;
const hands=[],raycaster=new THREE.Raycaster(),v3=new THREE.Vector3(),q4=new THREE.Quaternion();const savedCamera={p:new THREE.Vector3(),q:new THREE.Quaternion(),target:new THREE.Vector3()};
function say(t){notice=t;$('#status').textContent=t;drawMenu();}
function dispose(root){root.traverse(o=>{o.geometry?.dispose();for(const m of [o.material].flat().filter(Boolean)){m.map?.dispose();m.dispose();}});}
function releaseAll(){for(const h of hands)release(h,false);}
function capture(){return {format:'voynich-quest',version:1,scale:'metres in workspace; original physical scale unknown',entries:entries.map(e=>({id:e.id,scan:e.scan,kind:e.kind,root:relativeTransform(e.root,content),pieces:e.pieces.map(p=>({name:p.name,transform:relativeTransform(p,e.origin)}))})),snap,reference};}
function persist(){if(restoring)return;try{localStorage.setItem('voynich-quest-v1',JSON.stringify(capture()));}catch(e){say('Brak miejsca na zapis. Wyeksportuj projekt JSON.');}}
function remember(){if(restoring)return;undo.push(capture());if(undo.length>20)undo.shift();}
function setActive(e,piece=null){active=e;selectedPiece=piece;drawMenu();}
