 const e={id:record?.id||crypto.randomUUID(),scan,kind:type,root,origin,pieces,home:new Map(),ref:null};root.userData={assembly:e.id,scan,kind:type,depth:'interpretive relief',physical_scale:'unknown'};
 for(const o of pieces){o.userData.entryId=e.id;e.home.set(o.name,homeTransform(o));}
