 if(type!=='whole'){
  try{const tex=await new THREE.TextureLoader().loadAsync(`assets/images/${scan}.jpg`);tex.colorSpace=THREE.SRGBColorSpace;const plane=new THREE.Mesh(new THREE.PlaneGeometry(p.width/p.height,1),new THREE.MeshBasicMaterial({map:tex,transparent:true,opacity:.3,depthWrite:false,side:THREE.DoubleSide}));plane.position.z=-.025;plane.visible=reference;plane.userData.reference=true;origin.add(plane);e.ref=plane;}catch{}
 }
